import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec4, mix } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;
  const group = new Group();

  const colors = config.colors ?? config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const activeTimelines = [];
  const resourcesToDispose = [];

  // --- STAGE BACKDROP ---
  // A gradient background plane (~7x6 units at z=-2.5) to keep Stage depth rich
  const backdropGeom = new PlaneGeometry(7.5, 6.0);
  resourcesToDispose.push(backdropGeom);

  const backdropMat = new MeshBasicNodeMaterial();
  const inkColorNode = new Color(colors.ink);
  const surfaceColorNode = new Color(colors.surface);

  backdropMat.colorNode = mix(
    vec4(inkColorNode.r, inkColorNode.g, inkColorNode.b, 1.0),
    vec4(surfaceColorNode.r, surfaceColorNode.g, surfaceColorNode.b, 1.0),
    uv().y
  );
  backdropMat.depthWrite = false;

  const backdropMesh = new Mesh(backdropGeom, backdropMat);
  backdropMesh.position.set(0, -1.0, -2.5);
  group.add(backdropMesh);

  // --- ACCENT STRIP (Signal Red) ---
  const accentGeom = new PlaneGeometry(0.04, 1.2);
  resourcesToDispose.push(accentGeom);
  const accentMat = new MeshBasicNodeMaterial();
  accentMat.colorNode = vec4(new Color(colors.accent).r, new Color(colors.accent).g, new Color(colors.accent).b, 1.0);
  const accentStrip = new Mesh(accentGeom, accentMat);
  accentStrip.position.set(-1.8, 0, 0.01);
  group.add(accentStrip);

  // --- BILLBOARDED SPRITE ---
  const spriteWidth = 2.56;
  const spriteHeight = 1.6;
  const spriteGeom = new PlaneGeometry(spriteWidth, spriteHeight);
  resourcesToDispose.push(spriteGeom);

  const spriteMat = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false
  });
  resourcesToDispose.push(spriteMat);

  const spriteMesh = new Mesh(spriteGeom, spriteMat);
  // Slightly forward
  spriteMesh.position.set(0, 0, 0.1);
  group.add(spriteMesh);

  // Load the floating-accent texture
  const imageUrl = config.imageUrl ?? '/prism-mock/home/nodes/floating-accent.png';
  ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
    spriteMat.map = tex;
    spriteMat.needsUpdate = true;
  });

  // Track rendering for camera billboarding
  spriteMesh.onBeforeRender = (renderer, scene, camera) => {
    spriteMesh.quaternion.copy(camera.quaternion);
  };

  // --- TYPOGRAPHY ---
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const titleString = items[0]?.text ?? 'Journal';

  // Render Display Text
  const titleText = ctx.fontAtlas.createText(titleString, {
    fontSize: 96,
    color: colors.paper,
    align: 'center'
  });
  // Adjust position and depth layering
  titleText.position.set(0.1, -0.05, 0.35);
  group.add(titleText);

  // --- CINEMATIC PRIMITIVES ---
  const primitives = config.cinematicPrimitives ?? [];
  const activePrimitives = [];
  for (const prim of primitives) {
    if (ctx.primitives[prim.name]) {
      const p = ctx.primitives[prim.name](group, prim.params);
      if (p) {
        activePrimitives.push(p);
        if (p.timeline) activeTimelines.push(p.timeline);
      }
    }
  }

  // --- ENTRANCE ANIMATION ---
  // Subtle elegant fade-up for Nova Atelier aesthetic
  const tl = gsap.timeline({});
  activeTimelines.push(tl);

  tl.fromTo(group.position, 
    { y: group.position.y - 0.2 }, 
    { y: group.position.y, duration: 1.2, ease: 'power3.out' }
  );

  // Clean-up Hook
  group.userData = {
    handlers: {},
    cleanup() {
      activeTimelines.forEach(t => t.kill());
      activePrimitives.forEach(p => {
        if (typeof p.cleanup === 'function') p.cleanup();
      });
      resourcesToDispose.forEach(res => {
        if (res.dispose) res.dispose();
      });
    }
  };

  return group;
}
